    x: 0.5, y: 0.18, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Arial Black", color: COLORS.textLight, margin: 0
  });

  // Context statement
  slide.addText("State-of-the-art VLMs require massive compute and memory, making mobile and edge deployment impractical.", {
    x: 0.5, y: 1.1, w: 9, h: 0.5,
