: \"4\", title: \"Linear Projection\", desc: \"Maps visual features into SmolLM2's embedding space\" },\n    { num: \"5\", title: \"SmolLM2 Backbone\", desc: \"Causal language model (135M / 360M / 1.7B params)\" },\n  ];\n\n  const stepX = 0.5, stepY = 1.05, stepW = 5.0, stepH = 0.7, stepGap = 0.1;\n  steps.forEach((s, i) => {\n    const y = stepY + i * (stepH + stepGap);\n    // Number circle\n    slide.addShape(pres.shapes.OVAL, { x: stepX, y: y + 0.1, w: 0.45, h: 0.45, fill: { color: COLORS.accent } });\n    slide.addText(s.num, { x: stepX, y: y + 0.1, w: 0.45, h: 0.45,\n      fontSize: 14, fontFace: \"Arial\", color: \"FFFFFF\", bold: true, align: \"center\", valign: \"middle\", margin: 0 });\n    // Title\n    slide.addText(s.title, { x: stepX + 0.6, y: y + 0.05, w: stepW - 0.6, h: 0.35,\n      fontSize: 14, fontFace: \"Arial\", color: COLORS.textDark, bold: true, margin: 0 });\n    // Description\n    slide.addText(s.desc, { x: stepX + 0.6, y: y + 0.38, w: stepW - 0.6, h: 0.32,\n      fontSize: 10, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0 });\n  });\n\n  // Video note\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.85, w: 9.0, h: 0.5, fill: { color: \"ECFDF5\" } });\n  slide.addText(\"Video: Frames are sampled and processed identically to images through the same pipeline.\", {\n    x: 0.7, y: 4.92, w: 8.6, h: 0.35,\n    fontSize: 11, fontFace: \"Arial\", color: COLORS.accent, margin: 0\n  });\n\n  // Slide number\n  slide.addText(\"3 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Slide 4: Compute Allocation (Finding 1) ────────────────────────────────────\nasync function createSlide4(pres) {\n  const slide = pres.addSlide();\n  slide.background = { color: \"F8FAFC\" };\n\n  // Title bar\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });\n  slide.addText(\"Finding 1 — Balanced Encoder-LM Compute Allocation\", 