ize: 14, fontFace: \"Arial\", color: COLORS.accent, bold: true, margin: 0\n  });\n\n  slide.addText([\n    { text: \"Space-to-depth transform rearranges spatial features into channel dimension\", options: { breakLine: true } },\n    { text: \"Factor r groups pixels into blocks, stacking channels\", options: { breakLine: true } },\n    { text: \"Token count reduces by r² (e.g., r=4 → 16× fewer tokens)\", options: {} }\n  ], {\n    x: rightX, y: 1.5, w: 4.9, h: 1.1,\n    fontSize: 11, fontFace: \"Arial\", color: COLORS.textDark, margin: 0\n  });\n\n  // r=2 vs r=4 comparison table header\n  slide.addText(\"Token Reduction by Compression Factor\", {\n    x: rightX, y: 2.75, w: 5.0, h: 0.3,\n    fontSize: 12, fontFace: \"Arial\", color: COLORS.textDark, bold: true, margin: 0\n  });\n\n  // Comparison boxes\n  const compY = 3.1;\n  // r=2 box\n  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: compY, w: 2.3, h: 1.15, fill: { color: \"FEF3C7\" } });\n  slide.addText(\"r = 2\", { x: rightX, y: compY + 0.1, w: 2.3, h: 0.35,\n    fontSize: 14, fontFace: \"Arial\", color: \"92400E\", bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"4× token reduction\", { x: rightX, y: compY + 0.45, w: 2.3, h: 0.3,\n    fontSize: 11, fontFace: \"Arial\", color: \"92400E\", align: \"center\", margin: 0 });\n  slide.addText(\"Better for larger VLMs\", { x: rightX, y: compY + 0.75, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: \"92400E\", align: \"center\", margin: 0 });\n\n  // r=4 box\n  slide.addShape(pres.shapes.RECTANGLE, { x: rightX + 2.55, y: compY, w: 2.3, h: 1.15, fill: { color: \"ECFDF5\" } });\n  slide.addText(\"r = 4\", { x: rightX + 2.55, y: compY + 0.1, w: 2.3, h: 0.35,\n    fontSize: 14, fontFace: \"Arial\", color: COLORS.accent, bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"16× token reduction\", { x: rightX + 2.55, y: compY + 0.45, w: 2.3, h: 0.3,\n    fontSize: 11, fontFace: \"Arial\", color: COLORS.accent, align: \"center\", margin: 0 });\n  slide.addText(\"Optimal for small VLMs\", { x: rightX + 2.55, y: compY + 0.75, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: COLORS.accent, align: \"center\", margin: 0 });\n\n  // Bottom note\n  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 4.4, w: 4.9, h: 0.65, fill: { color: COLORS.midBg } });\n  slide.addText(\"Aggressive compression eases attention overhead and enables longer-context modeling for small VLMs.\", {\n    x: rightX + 0.15, y: 4.48, w: 4.6, h: 0.5,\n    fontSize: 10.5, fontFace: \"Arial\", color: COLORS.textLight, margin: 0\n  });\n\n  // Slide number\n  slide.addText(\"5 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Slide 6: Context Length Scaling (Finding 2) ──────────────────────────────\nasync function createSlide6(pres) {\n  const slide = pres.addSlide();\n  slide.background = { color: \"F8FAFC\" };\n\n  // Title bar\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });\n  slide.addText(\"Finding 2 — Extended Context: 2K → 16K Tokens\", {\n    x: 0.5, y: 0.18, w: 9, h: 0.55,\n    fontSize: 24, fontFace: \"Arial Black\", color: COLORS.textLight, margin: 0\n  });\n\n  // Context extension diagram (left)\n  const diagramX = 0.5, diagramY = 1.15;\n  // Before box\n  slide.addShape(pres.shapes.RECTANGLE, { x: diagramX, y: diagramY, w: 2.3, h: 1.6, fill: { color: \"FEF2F2\" } });\n  slide.addText(\"Before\", { x: diagramX, y: diagramY + 0.1, w: 2.3, h: 0.3,\n    fontSize: 12, fontFace: \"Arial\", color: \"991B1B\", bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"2K context\", { x: diagramX, y: diagramY + 0.45, w: 2.3, h: 0.35,\n    fontSize: 18, fontFace: \"Arial\", color: \"991B1B\", bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"RoPE base: 10K\", { x: diagramX, y: diagramY + 0.9, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: \"991B1B\", align: \"center\", margin: 0 });\n  slide.addText(\"Lower resolution\", { x: diagramX, y: diagramY + 1.2, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: \"991B1B\", align: \"center\", margin: 0 });\n\n  // Arrow\n  slide.addShape(pres.shapes.RECTANGLE, { x: diagramX + 2.5, y: diagramY + 0.7, w: 0.6, h: 0.08, fill: { color: COLORS.accent } });\n  slide.addText(\"→\", { x: diagramX + 2.45, y: diagramY + 0.45, w: 0.7, h: 0.6,\n    fontSize: 24, fontFace: \"Arial\", color: COLORS.accent, bold: true, align: \"center\", valign: \"middle\", margin: 0 });\n\n  // After box\n  slide.addShape(pres.shapes.RECTANGLE, { x: diagramX + 3.3, y: diagramY, w: 2.3, h: 1.6, fill: { color: \"ECFDF5\" } });\n  slide.addText(\"After\", { x: diagramX + 3.3, y: diagramY + 0.1, w: 2.3, h: 0.3,\n    fontSize: 12, fontFace: \"Arial\", color: \"065F46\", bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"16K context\", { x: diagramX + 3.3, y: diagramY + 0.45, w: 2.3, h: 0.35,\n    fontSize: 18, fontFace: \"Arial\", color: \"065F46\", bold: true, align: \"center\", margin: 0 });\n  slide.addText(\"RoPE base: 273K\", { x: diagramX + 3.3, y: diagramY + 0.9, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: \"065F46\", align: \"center\", margin: 0 });\n  slide.addText(\"Higher resolution\", { x: diagramX + 3.3, y: diagramY + 1.2, w: 2.3, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: \"065F46\", align: \"center\", margin: 0 });\n\n  // Right side: key changes\n  const rightX = 6.3;\n  slide.addText(\"Implementation Details\", {\n    x: rightX, y: 1.1, w: 3.4, h: 0.35,\n    fontSize: 14, fontFace: \"Arial\", color: COLORS.accent, bold: true, margin: 0\n  });\n\n  const details = [\n    { label: \"RoPE Base\", value: \"10K → 273K\", desc: \"Extended rotary position embeddings\" },\n    { label: \"Fine-tuning\", value: \"Mixed context\", desc: \"Long + short context data\" },\n    { label: \"2.2B model\", value: \"16K tokens\", desc: \"Full context extension\" },\n    { label: \"256M / 500M\", value: \"8K tokens\", desc: \"Scaled proportionally\" },\n  ];\n\n  details.forEach((d, i) => {\n    const y = 1.55 + i * 0.7;\n    slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y, w: 3.4, h: 0.6, fill: { color: COLORS.cardBg }, shadow: makeShadow() });\n    slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y, w: 0.06, h: 0.6, fill: { color: COLORS.accent } });\n    slide.addText(d.label, { x: rightX + 0.15, y: y + 0.05, w: 1.6, h: 0.25,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0 });\n    slide.addText(d.value, { x: rightX + 0.15, y: y + 0.28, w: 1.6, h: 0.25,\n      fontSize: 12, fontFace: \"Arial\", color: COLORS.textDark, bold: true, margin: 0 });\n    slide.addText(d.desc, { x: rightX + 1.7, y: y + 0.12, w: 1.55, h: 0.4,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0 });\n  });\n\n  // Impact statement\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.65, w: 9.0, h: 0.7, fill: { color: COLORS.midBg } });\n  slide.addText(\"Impact: Significant benchmark gains — higher resolution images unlock more visual reasoning capacity.\", {\n    x: 0.7, y: 4.75, w: 8.6, h: 0.5,\n    fontSize: 12, fontFace: \"Arial\", color: COLORS.accentLight, bold: true, margin: 0\n  });\n\n  // Slide number\n  slide.addText(\"6 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Slide 7: Benchmark Performance ───────────────────────────────────────────\nasync function createSlide7(pres) {\n  const slide = pres.addSlide();\n  slide.background = { color: \"F8FAFC\" };\n\n  // Title bar\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });\n  slide.addText(\"Benchmark Performance: Competitive at Sub-1GB RAM\", {\n    x: 0.5, y: 0.18, w: 9, h: 0.55,\n    fontSize: 24, fontFace: \"Arial Black\", color: COLORS.textLight, margin: 0\n  });\n\n  // Summary callouts (top row)\n  const summary = [\n    { label: \"SmolVLM 256M\", value: \"44.0%\", sub: \"0.8 GB RAM\", color: COLORS.accent },\n    { label: \"SmolVLM 500M\", value: \"51.0%\", sub: \"1.2 GB RAM\", color: COLORS.accentLight },\n    { label: \"SmolVLM 2.2B\", value: \"59.8%\", sub: \"4.9 GB RAM\", color: COLORS.chartPurple },\n  ];\n\n  const sumX = 0.5, sumW = 2.9, sumY = 1.0, sumGap = 0.25;\n  summary.forEach((s, i) => {\n    const x = sumX + i * (sumW + sumGap);\n    slide.addShape(pres.shapes.RECTANGLE, { x, y: sumY, w: sumW, h: 0.85, fill: { color: COLORS.cardBg }, shadow: makeShadow() });\n    slide.addShape(pres.shapes.RECTANGLE, { x, y: sumY, w: sumW, h: 0.06, fill: { color: s.color } });\n    slide.addText(s.label, { x, y: sumY + 0.12, w: sumW, h: 0.25,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, align: \"center\", margin: 0 });\n    slide.addText(s.value, { x, y: sumY + 0.32, w: sumW, h: 0.35,\n      fontSize: 20, fontFace: \"Arial\", color: COLORS.textDark, bold: true, align: \"center\", margin: 0 });\n    slide.addText(s.sub, { x, y: sumY + 0.62, w: sumW, h: 0.2,\n      fontSize: 9, fontFace: \"Arial\", color: s.color, align: \"center\", margin: 0 });\n  });\n\n  // Benchmark table\n  const tableX = 0.5, tableY = 2.0;\n  const headers = [\n    [\n      { text: \"Capability\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"left\" } },\n      { text: \"Benchmark\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"left\" } },\n      { text: \"256M\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"center\" } },\n      { text: \"500M\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"center\" } },\n      { text: \"2.2B\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"center\" } },\n      { text: \"Efficient OS\", options: { fill: { color: COLORS.midBg }, color: COLORS.textLight, bold: true, align: \"center\" } },\n    ]\n  ];\n\n  const rows = [\n    [\"Single-Image\", \"OCRBench\", \"52.6%\", \"61.0%\", \"72.9%\", \"54.7% (Molmo)\"],\n    [\"Single-Image\", \"AI2D\", \"46.4%\", \"59.2%\", \"70.0%\", \"71.0% (Molmo)\"],\n    [\"Single-Image\", \"ChartQA\", \"55.6%\", \"62.8%\", \"68.7%\", \"48.0% (Molmo)\"],\n    [\"Single-Image\", \"TextVQA\", \"50.2%\", \"60.2%\", \"73.0%\", \"61.5% (Molmo)\"],\n    [\"Single-Image\", \"DocVQA\", \"58.3%\", \"70.5%\", \"80.0%\", \"77.7% (Molmo)\"],\n    [\"Single-Image\", \"ScienceQA\", \"73.8%\", \"80.0%\", \"89.6%\", \"87.5% (Molmo)\"],\n    [\"Multi-task\", \"MMMU\", \"29.0%\", \"33.7%\", \"42.0%\", \"33.9% (Molmo)\"],\n    [\"Multi-task\", \"MathVista\", \"35.9%\", \"40.1%\", \"51.5%\", \"37.6% (Molmo)\"],\n    [\"Multi-task\", \"MMStar\", \"34.6%\", \"38.3%\", \"46.0%\", \"43.1% (Molmo)\"],\n    [\"Video\", \"Video-MME\", \"33.7%\", \"42.2%\", \"52.1%\", \"45.0% (InternVL2)\"],\n    [\"Video\", \"MLVU\", \"40.6%\", \"47.3%\", \"55.2%\", \"48.2% (InternVL2)\"],\n  ];\n\n  const rowData = rows.map((r, ri) => {\n    const bgColor = ri % 2 === 0 ? \"FFFFFF\" : \"F8FAFC\";\n    return [\n      { text: r[0], options: { fill: { color: bgColor }, color: COLORS.textMuted, fontSize: 8, align: \"left\" } },\n      { text: r[1], options: { fill: { color: bgColor }, color: COLORS.textDark, fontSize: 8, bold: true, align: \"left\" } },\n      { text: r[2], options: { fill: { color: bgColor }, color: COLORS.textDark, fontSize: 8, align: \"center\" } },\n      { text: r[3], options: { fill: { color: bgColor }, color: COLORS.textDark, fontSize: 8, align: \"center\" } },\n      { text: r[4], options: { fill: { color: bgColor }, color: COLORS.textDark, fontSize: 8, align: \"center\" } },\n      { text: r[5], options: { fill: { color: bgColor }, color: COLORS.textMuted, fontSize: 8, align: \"center\" } },\n    ];\n  });\n\n  const avgRow = [\n    { text: \"Average\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.textDark, fontSize: 9, bold: true, align: \"left\" } },\n    { text: \"All 11 Benchmarks\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.textDark, fontSize: 9, bold: true, align: \"left\" } },\n    { text: \"44.0%\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.accent, fontSize: 9, bold: true, align: \"center\" } },\n    { text: \"51.0%\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.accentLight, fontSize: 9, bold: true, align: \"center\" } },\n    { text: \"59.8%\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.chartPurple, fontSize: 9, bold: true, align: \"center\" } },\n    { text: \"—\", options: { fill: { color: \"ECFDF5\" }, color: COLORS.textMuted, fontSize: 9, align: \"center\" } },\n  ];\n\n  const tableData = [...headers, ...rowData, avgRow];\n  slide.addTable(tableData, {\n    x: tableX, y: tableY, w: 9.0, h: 3.0,\n    colW: [1.3, 1.3, 0.8, 0.8, 0.8, 2.0],\n    fontSize: 8, fontFace: \"Arial\",\n    border: { pt: 0.5, color: COLORS.border },\n    valign: \"middle\",\n  });\n\n  // RAM comparison note\n  slide.addText(\"RAM: SmolVLM-256M: 0.8GB | 500M: 1.2GB | 2.2B: 4.9GB  vs.  Molmo-A1B-7B: 27.7GB  (35× more)\", {\n    x: 0.5, y: 5.15, w: 9.0, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0\n  });\n\n  // Slide number\n  slide.addText(\"7 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Slide 8: On-Device Deployment ────────────────────────────────────────────\nasync function createSlide8(pres) {\n  const slide = pres.addSlide();\n  slide.background = { color: \"F8FAFC\" };\n\n  // Title bar\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });\n  slide.addText(\"Real-Time Inference on Apple Silicon\", {\n    x: 0.5, y: 0.18, w: 9, h: 0.55,\n    fontSize: 26, fontFace: \"Arial Black\", color: COLORS.textLight, margin: 0\n  });\n\n  // App screenshot (left)\n  try {\n    const imgData = await sharp(\"/app/benchmark/assets/figure_2.jpg\")\n      .resize({ width: 300 })\n      .toBuffer();\n    const base64 = \"image/jpeg;base64,\" + imgData.toString(\"base64\");\n    slide.addImage({ data: base64, x: 0.5, y: 1.1, w: 3.2, h: 2.8 });\n  } catch (e) { /* skip */ }\n\n  // Throughput metrics (right)\n  const rightX = 3.95;\n\n  slide.addText(\"HuggingSnap iOS App — Local Inference\", {\n    x: rightX, y: 1.05, w: 5.7, h: 0.35,\n    fontSize: 13, fontFace: \"Arial\", color: COLORS.accent, bold: true, margin: 0\n  });\n\n  slide.addText(\"Photos and videos processed entirely on-device — no cloud dependency.\", {\n    x: rightX, y: 1.42, w: 5.7, h: 0.3,\n    fontSize: 10, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0\n  });\n\n  // Device metrics cards\n  const devices = [\n    { device: \"Pro M1 Max 64GB\", tokens: \"~80 tok/s\", batch: \"1\", color: COLORS.accent },\n    { device: \"Pro M1 Max 64GB (batch 64)\", tokens: \"~1000 tok/s\", batch: \"64\", color: COLORS.chartPurple },\n    { device: \"MacBook Air M3 16GB\", tokens: \"~55 tok/s\", batch: \"1\", color: COLORS.accentLight },\n  ];\n\n  devices.forEach((d, i) => {\n    const y = 1.85 + i * 0.75;\n    slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y, w: 5.7, h: 0.65, fill: { color: COLORS.cardBg }, shadow: makeShadow() });\n    slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y, w: 0.06, h: 0.65, fill: { color: d.color } });\n    slide.addText(d.device, { x: rightX + 0.2, y: y + 0.08, w: 3.0, h: 0.25,\n      fontSize: 10, fontFace: \"Arial\", color: COLORS.textDark, bold: true, margin: 0 });\n    slide.addText(d.tokens, { x: rightX + 3.2, y: y + 0.05, w: 2.3, h: 0.3,\n      fontSize: 16, fontFace: \"Arial\", color: d.color, bold: true, align: \"right\", margin: 0 });\n    slide.addText(`batch ${d.batch}`, { x: rightX + 3.2, y: y + 0.38, w: 2.3, h: 0.22,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, align: \"right\", margin: 0 });\n  });\n\n  // Linear scaling note\n  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 4.2, w: 5.7, h: 0.55, fill: { color: \"F0FDF4\" } });\n  slide.addText(\"Throughput scales linearly with batch size for SmolVLM-256M\", {\n    x: rightX + 0.2, y: 4.3, w: 5.3, h: 0.35,\n    fontSize: 10, fontFace: \"Arial\", color: \"166534\", margin: 0\n  });\n\n  // Key stats at bottom\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.9, w: 10, h: 0.725, fill: { color: COLORS.midBg } });\n  const stats = [\n    { v: \"80\", u: \"tok/s\", l: \"on M1 Max Pro\" },\n    { v: \"1000\", u: \"tok/s\", l: \"batch 64 on M1 Max\" },\n    { v: \"0.8GB\", u: \"\", l: \"GPU RAM at batch 1\" },\n  ];\n  const statX = 0.5, statW = 3.0;\n  stats.forEach((s, i) => {\n    const x = statX + i * statW;\n    slide.addText(s.v + s.u, { x, y: 4.98, w: statW, h: 0.35,\n      fontSize: 16, fontFace: \"Arial\", color: COLORS.accentLight, bold: true, align: \"center\", margin: 0 });\n    slide.addText(s.l, { x, y: 5.32, w: statW, h: 0.25,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, align: \"center\", margin: 0 });\n  });\n\n  // Slide number\n  slide.addText(\"8 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Slide 9: Key Takeaways ─────────────────────────────────────────────────────\nasync function createSlide9(pres) {\n  const slide = pres.addSlide();\n  slide.background = { color: COLORS.darkBg };\n\n  // Title\n  slide.addText(\"Design Principles for Efficient Multimodal Models\", {\n    x: 0.5, y: 0.35, w: 9, h: 0.7,\n    fontSize: 28, fontFace: \"Arial Black\", color: COLORS.textLight, margin: 0\n  });\n\n  // 5 takeaway cards in a grid\n  const takeaways = [\n    { num: \"01\", title: \"Balance Encoder-LM Compute\", desc: \"Don't overspend on vision encoder for small VLMs. 93M SigLIP-B/16 outperforms 428M SO400M for LM < 1B.\" },\n    { num: \"02\", title: \"Extend Context Length\", desc: \"RoPE base 10K → 273K enables 16K context. Higher resolution unlocks more visual reasoning capacity.\" },\n    { num: \"03\", title: \"Aggressive Token Compression\", desc: \"r=4 (16× reduction) is optimal for small VLMs — eases attention overhead and improves long-context modeling.\" },\n    { num: \"04\", title: \"Sub-1GB Inference Achievable\", desc: \"SmolVLM-256M at 0.8GB surpasses the 300× larger Idefics-80B. Architectural efficiency > raw scale.\" },\n    { num: \"05\", title: \"Fully Open-Source\", desc: \"All weights, datasets, code, and HuggingSnap mobile app are released to promote reproducibility.\" },\n  ];\n\n  // Layout: 3 on top row, 2 on bottom row\n  const cardW = 2.85, cardH = 1.25, gapX = 0.25, gapY = 0.2;\n  const startY = 1.2;\n  const positions = [\n    { x: 0.5, y: startY },\n    { x: 0.5 + cardW + gapX, y: startY },\n    { x: 0.5 + 2 * (cardW + gapX), y: startY },\n    { x: 1.67, y: startY + cardH + gapY },\n    { x: 1.67 + cardW + gapX, y: startY + cardH + gapY },\n  ];\n\n  takeaways.forEach((t, i) => {\n    const { x, y } = positions[i];\n    slide.addShape(pres.shapes.RECTANGLE, { x, y, w: cardW, h: cardH, fill: { color: COLORS.midBg } });\n    slide.addShape(pres.shapes.RECTANGLE, { x, y, w: cardW, h: 0.06, fill: { color: COLORS.accent } });\n\n    slide.addText(t.num, {\n      x: x + 0.12, y: y + 0.12, w: 0.4, h: 0.35,\n      fontSize: 14, fontFace: \"Arial\", color: COLORS.accentLight, bold: true, margin: 0\n    });\n    slide.addText(t.title, {\n      x: x + 0.5, y: y + 0.12, w: cardW - 0.6, h: 0.3,\n      fontSize: 11, fontFace: \"Arial\", color: COLORS.textLight, bold: true, margin: 0\n    });\n    slide.addText(t.desc, {\n      x: x + 0.12, y: y + 0.5, w: cardW - 0.24, h: 0.7,\n      fontSize: 9, fontFace: \"Arial\", color: COLORS.textMuted, margin: 0\n    });\n  });\n\n  // Bottom tagline\n  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: \"0A1628\" } });\n  slide.addText(\"SmolVLM — arXiv:2504.05299 — huggingface.co/smolvlm\", {\n    x: 0.5, y: 4.95, w: 9, h: 0.4,\n    fontSize: 12, fontFace: \"Arial\", color: COLORS.accentLight, align: \"center\", margin: 0\n  });\n\n  // Slide number\n  slide.addText(\"9 / 9\", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: \"right\", margin: 0 });\n}\n\n// ── Build & Save ───────────────────────────────────────────────────────────────\n(async () => {\n  await createSlide1(pres);\n  await createSlide2(pres);\n  await createSlide3(pres);\n  await createSlide4(pres);\n  await createSlide5(pres);\n  await createSlide6(pres);\n  await createSlide7(pres);\n  await createSlide8(pres);\n  await createSlide9(pres);\n\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"Saved: /app/output/final_deck.pptx\");\n})();", "numLines": 693, "startLine": 1, "totalLines": 693}}

