const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaMicrochip, FaChartBar, FaCompressAlt, FaMobileAlt, FaLightbulb, FaRocket } = require("react-icons/fa");
const { MdMemory, MdAutoGraph } = require("react-icons/md");
const { HiDocumentText, HiLightBulb } = require("react-icons/hi");

// ── Helpers ───────────────────────────────────────────────────────────────────
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

const makeShadow = () => ({ type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

// ── Presentation Setup ─────────────────────────────────────────────────────────
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "SmolVLM: Redefining Small and Efficient Multimodal Models";
pres.author = "Hugging Face & Stanford";

// Color palette - technical/deep blue theme
const COLORS = {
  darkBg: "0F172A",      // Deep navy for title slides
  midBg: "1E293B",       // Slate for section headers
  cardBg: "FFFFFF",      // White cards
  accent: "0D9488",      // Teal accent
  accentLight: "14B8A6", // Lighter teal
  textDark: "1E293B",    // Dark text
  textMuted: "64748B",   // Muted text
  textLight: "F8FAFC",   // Light text
  border: "E2E8F0",      // Light border
  highlight: "F59E0B",   // Amber highlight
  chartBlue: "3B82F6",
  chartGreen: "10B981",
  chartPurple: "8B5CF6",
};

// ── Slide 1: Title ─────────────────────────────────────────────────────────────
async function createSlide1(pres) {
  const slide = pres.addSlide();
  slide.background = { color: COLORS.darkBg };

  // Left accent bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: COLORS.accent } });

  // Decorative circles (top right)
  slide.addShape(pres.shapes.OVAL, { x: 8.5, y: 0.3, w: 1.2, h: 1.2, fill: { color: COLORS.accent, transparency: 30 } });
  slide.addShape(pres.shapes.OVAL, { x: 9.2, y: 1.1, w: 0.6, h: 0.6, fill: { color: COLORS.accentLight, transparency: 40 } });

  // Main title
  slide.addText("SmolVLM", {
    x: 0.6, y: 1.4, w: 9, h: 1.0,
    fontSize: 54, fontFace: "Arial Black", color: COLORS.textLight,
    bold: true, margin: 0
  });

  slide.addText("Redefining Small and Efficient Multimodal Models", {
    x: 0.6, y: 2.4, w: 9, h: 0.7,
    fontSize: 24, fontFace: "Arial", color: COLORS.accentLight,
    bold: false, margin: 0
  });

  // Authors
  slide.addText("Hugging Face & Stanford University", {
    x: 0.6, y: 3.4, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Arial", color: COLORS.textMuted, margin: 0
  });

  // Bottom tagline
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 4.8, w: 10, h: 0.825, fill: { color: COLORS.midBg } });
  slide.addText("Compact Vision-Language Models  ·  Sub-1GB Inference  ·  On-Device AI", {
    x: 0.6, y: 4.95, w: 9, h: 0.4,
    fontSize: 13, fontFace: "Arial", color: COLORS.textMuted, margin: 0
  });
}

// ── Slide 2: Problem / Motivation ────────────────────────────────────────────
async function createSlide2(pres) {
  const slide = pres.addSlide();
  slide.background = { color: "F8FAFC" };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });
  slide.addText("The Edge Deployment Problem", {
    x: 0.5, y: 0.18, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Arial Black", color: COLORS.textLight, margin: 0
  });

  // Context statement
  slide.addText("State-of-the-art VLMs require massive compute and memory, making mobile and edge deployment impractical.", {
    x: 0.5, y: 1.1, w: 9, h: 0.5,
    fontSize: 13, fontFace: "Arial", color: COLORS.textMuted, margin: 0
  });

  // Comparison cards - 3 across
  const models = [
    { name: "Idefics-80B", params: "80B params", ram: "~32GB+", scale: "300× larger", color: "DC2626" },
    { name: "Molmo-A1B-7B", params: "7B params", ram: "27.7GB", scale: "35× larger", color: "F59E0B" },
    { name: "InternVL2-2B", params: "2B params", ram: "~10GB", scale: "10× larger", color: "7C3AED" },
  ];

  const cardW = 2.8, cardH = 2.0, startX = 0.55, gap = 0.35, cardY = 1.75;
  models.forEach((m, i) => {
    const x = startX + i * (cardW + gap);
    // Card background
    slide.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: cardH, fill: { color: COLORS.cardBg }, shadow: makeShadow() });
    // Top accent
    slide.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: 0.08, fill: { color: m.color } });
    // Model name
    slide.addText(m.name, { x, y: cardY + 0.2, w: cardW, h: 0.4,
      fontSize: 16, fontFace: "Arial", color: COLORS.textDark, bold: true, align: "center", margin: 0 });
    // Params
    slide.addText(m.params, { x, y: cardY + 0.65, w: cardW, h: 0.35,
      fontSize: 12, fontFace: "Arial", color: COLORS.textMuted, align: "center", margin: 0 });
    // RAM badge
    slide.addShape(pres.shapes.RECTANGLE, { x: x + 0.3, y: cardY + 1.05, w: cardW - 0.6, h: 0.35, fill: { color: "FEF2F2" } });
    slide.addText(m.ram, { x: x + 0.3, y: cardY + 1.05, w: cardW - 0.6, h: 0.35,
      fontSize: 13, fontFace: "Arial", color: m.color, bold: true, align: "center", valign: "middle", margin: 0 });
    // Scale label
    slide.addText(m.scale, { x, y: cardY + 1.5, w: cardW, h: 0.35,
      fontSize: 11, fontFace: "Arial", color: COLORS.textMuted, align: "center", margin: 0 });
  });

  // Bottom insight box
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.55, y: 4.05, w: 9.0, h: 0.8, fill: { color: COLORS.midBg } });
  slide.addText("Goal: Achieve competitive performance with <1GB GPU RAM — enabling true on-device inference.", {
    x: 0.75, y: 4.2, w: 8.6, h: 0.5,
    fontSize: 13, fontFace: "Arial", color: COLORS.accentLight, bold: true, margin: 0
  });

  // Slide number
  slide.addText("2 / 9", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: "right", margin: 0 });
}

// ── Slide 3: Architecture Overview ─────────────────────────────────────────────
async function createSlide3(pres) {
  const slide = pres.addSlide();
  slide.background = { color: "F8FAFC" };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });
  slide.addText("SmolVLM Architecture Pipeline", {
    x: 0.5, y: 0.18, w: 9, h: 0.55,
    fontSize: 26, fontFace: "Arial Black", color: COLORS.textLight, margin: 0
  });

  // Architecture image (right side)
  try {
    const imgData = await sharp("/app/benchmark/assets/figure_3.jpg")
      .resize({ height: 280 })
      .toBuffer();
    const base64 = "image/jpeg;base64," + imgData.toString("base64");
    slide.addImage({ data: base64, x: 5.6, y: 1.1, w: 4.2, h: 2.8 });
  } catch (e) { /* skip */ }

  // Pipeline steps (left side)
  const steps = [
    { num: "1", title: "Image Splitting", desc: "Input image is divided into sub-images (tiles) for efficient processing" },
    { num: "2", title: "SigLIP Vision Encoder", desc: "Encodes each tile with a lightweight SigLIP-B/16 (93M params)" },
    { num: "3", title: "Pixel Shuffle", desc: "Space-to-depth transform reduces tokens 16× at r=4" },
    { num: "4", title: "Linear Projection", desc: "Maps visual features into SmolLM2's embedding space" },
    { num: "5", title: "SmolLM2 Backbone", desc: "Causal language model (135M / 360M / 1.7B params)" },
  ];

  const stepX = 0.5, stepY = 1.05, stepW = 5.0, stepH = 0.7, stepGap = 0.1;
  steps.forEach((s, i) => {
    const y = stepY + i * (stepH + stepGap);
    // Number circle
    slide.addShape(pres.shapes.OVAL, { x: stepX, y: y + 0.1, w: 0.45, h: 0.45, fill: { color: COLORS.accent } });
    slide.addText(s.num, { x: stepX, y: y + 0.1, w: 0.45, h: 0.45,
      fontSize: 14, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0 });
    // Title
    slide.addText(s.title, { x: stepX + 0.6, y: y + 0.05, w: stepW - 0.6, h: 0.35,
      fontSize: 14, fontFace: "Arial", color: COLORS.textDark, bold: true, margin: 0 });
    // Description
    slide.addText(s.desc, { x: stepX + 0.6, y: y + 0.38, w: stepW - 0.6, h: 0.32,
      fontSize: 10, fontFace: "Arial", color: COLORS.textMuted, margin: 0 });
  });

  // Video note
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.85, w: 9.0, h: 0.5, fill: { color: "ECFDF5" } });
  slide.addText("Video: Frames are sampled and processed identically to images through the same pipeline.", {
    x: 0.7, y: 4.92, w: 8.6, h: 0.35,
    fontSize: 11, fontFace: "Arial", color: COLORS.accent, margin: 0
  });

  // Slide number
  slide.addText("3 / 9", { x: 9.2, y: 5.2, w: 0.6, h: 0.3, fontSize: 10, color: COLORS.textMuted, align: "right", margin: 0 });
}

// ── Slide 4: Compute Allocation (Finding 1) ────────────────────────────────────
async function createSlide4(pres) {
  const slide = pres.addSlide();
  slide.background = { color: "F8FAFC" };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.9, fill: { color: COLORS.darkBg } });
  slide.addText("Finding 1 — Balanced Encoder-LM Compute Allocation", {
    x: 0.5, y: 0.18, w: 9, h: 0.55,
    fontSize: 24, fontFace: "Arial Black", color: COLORS.textLight, margin: 0
  });

  // Subtitle
  slide.addText("Smaller vision encoders outperform larger ones for compact VLMs", {
    x: 0.5, y: 1.05, w: 9, h: 0.35,
    fontSize: 13, fontFace: "Arial", color: COLORS.textMuted, margin: 0
  });

  // Bar chart comparing encoder sizes
  const chartData = [
    {
      name: "SigLIP-B/16 (93M)",
      labels: ["256M LM", "500M LM", "2.2B LM"],
      values: [48.2, 54.5, 61.0]
    },
    {
      name: "SigLIP-SO400M (428M)",
      labels: ["256M LM", "500M LM", "2.2B LM"],
      values: [44.8, 52.8, 62.5]
    }
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.5, w: 5.8, h: 3.2, barDir: "col",
    chartColors: [COLORS.accent, COLORS.chartPurple],
    chartArea: { fill: { color: "FFFFFF" }, roundedCorners: true },
    catAxisLabelColor: COLORS.textMuted,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: COLORS.textMuted,
    valAxisLabelFontSize: 9,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
